class SQLiteSessionStore extends session.Store {
  get(sid:string,callback:(err:Error|null,sess?:session.SessionData|null)=>void){try{const row=db.prepare('SELECT sess,expired FROM sessions WHERE sid=?').get(sid) as {sess:string;expired:number}|undefined;if(!row||row.expired<Date.now()){if(row)db.prepare('DELETE FROM sessions WHERE sid=?').run(sid);callback(null,null);return;}callback(null,JSON.parse(row.sess));}catch(e){callback(e as Error);}}
  set(sid:string,sess:session.SessionData,callback?:(err?:Error|null)=>void){try{const expired=Date.now()+(sess.cookie.maxAge??86400000);db.prepare('INSERT INTO sessions(sid,sess,expired) VALUES(?,?,?) ON CONFLICT(sid) DO UPDATE SET sess=excluded.sess,expired=excluded.expired').run(sid,JSON.stringify(sess),expired);callback?.(null);}catch(e){callback?.(e as Error);}}
  destroy(sid:string,callback?:(err?:Error|null)=>void){try{db.prepare('DELETE FROM sessions WHERE sid=?').run(sid);callback?.(null);}catch(e){callback?.(e as Error);}}
  touch(sid:string,sess:session.SessionData,callback?:(err?:Error|null)=>void){try{db.prepare('UPDATE sessions SET expired=? WHERE sid=?').run(Date.now()+(sess.cookie.maxAge??86400000),sid);callback?.(null);}catch(e){callback?.(e as Error);}}
}
app.use(session({ store: new SQLiteSessionStore(), secret: process.env.SESSION_SECRET ?? 'smartfood-local-dev-secret-change-me', resave: false, saveUninitialized: false, name: 'smartfood.sid', cookie: { httpOnly: true, sameSite: 'lax', secure: process.env.NODE_ENV === 'production', maxAge: 1000 * 60 * 60 * 12 } }));

declare module 'express-session' { interface SessionData { userId?: number; csrf?: string } }
type Role = 'DONOR'|'NGO'|'VOLUNTEER'|'ADMIN';
type User = { id:number; email:string; role:Role; name:string; status:string; verified:number; address:string|null; lat:number|null; lng:number|null; capacity:number; available:number };
const userQuery = db.prepare('SELECT id,email,role,name,status,verified,address,lat,lng,capacity,available FROM users WHERE id=?');
function currentUser(req: express.Request): User | undefined { return req.session.userId ? userQuery.get(req.session.userId) as User|undefined : undefined; }
function auth(req: express.Request,res: express.Response,next: express.NextFunction) { const user=currentUser(req); if(!user || user.status!=='ACTIVE'){ req.session.destroy(()=>{}); return res.status(401).json({error:'Please sign in to continue.'}); } res.locals.user=user; next(); }
function roles(...allowed: Role[]) { return (req:express.Request,res:express.Response,next:express.NextFunction) => { const u=res.locals.user as User; if(!allowed.includes(u.role)) return res.status(403).json({error:'You do not have access to this action.'}); next(); }; }
function csrf(req:express.Request,res:express.Response,next:express.NextFunction) { if(['GET','HEAD','OPTIONS'].includes(req.method)) return next(); if(!req.session.csrf || req.get('x-csrf-token')!==req.session.csrf) return res.status(403).json({error:'Security token expired. Refresh and try again.'}); next(); }
function notify(userId:number,title:string,body:string,link:string,dedupeKey?:string){db.prepare('INSERT OR IGNORE INTO notifications(user_id,title,body,link,dedupe_key) VALUES(?,?,?,?,?)').run(userId,title,body,link,dedupeKey??null);}
function expireDonation(id:number,actorId:number|null){const d=db.prepare("SELECT * FROM donations WHERE id=? AND expires_at<=? AND status NOT IN ('EXPIRED','CANCELLED','RECEIVED')").get(id,new Date().toISOString()) as any;if(!d)return false;db.transaction(()=>{db.prepare("UPDATE donations SET status='EXPIRED',available_quantity=0 WHERE id=?").run(id);db.prepare("UPDATE claims SET status='REJECTED',reason='Donation expired before rescue.' WHERE donation_id=? AND status='PENDING'").run(id);db.prepare("UPDATE assignments SET status='CANCELLED' WHERE donation_id=? AND status IN ('OFFERED','ACCEPTED','PICKUP_STARTED','PICKED_UP','IN_TRANSIT')").run(id);event(id,'EXPIRED',actorId,'Expired food is no longer available; pending claims and active assignments are cancelled, with history retained.');audit(actorId,'DONATION_EXPIRED','donation',id);const recipients=db.prepare("SELECT id FROM users WHERE role IN ('DONOR','ADMIN') UNION SELECT c.ngo_id FROM claims c WHERE c.donation_id=? UNION SELECT a.volunteer_id FROM assignments a WHERE a.donation_id=?").all(id,id) as {id:number}[];for(const u of recipients)notify(u.id,'Donation expired',`${d.title} is no longer available.`,`/donations/${id}`,`expire-${id}-${u.id}`);})();return true;}
function runMaintenance(){const now=new Date().toISOString();for(const d of db.prepare("SELECT id FROM donations WHERE expires_at<=? AND status NOT IN ('EXPIRED','CANCELLED','RECEIVED')").all(now) as {id:number}[])expireDonation(d.id,null);const emergencies=db.prepare("SELECT d.*,c.name category FROM donations d JOIN categories c ON c.id=d.category_id WHERE d.status='AVAILABLE' AND d.expires_at>? AND d.expires_at<=?").all(now,new Date(Date.now()+2*3600000).toISOString()) as any[];for(const d of emergencies){if(!db.prepare("SELECT 1 FROM timeline_events WHERE donation_id=? AND event_type='EMERGENCY_ALERT'").get(d.id))event(d.id,'EMERGENCY_ALERT',null,'Under two hours remain; nearby partners have been notified.');const nearby=db.prepare("SELECT id,lat,lng FROM users WHERE role='NGO' AND verified=1 AND status='ACTIVE' UNION SELECT id,lat,lng FROM users WHERE role='VOLUNTEER' AND available=1 AND status='ACTIVE'").all() as any[];for(const u of nearby)if(u.lat!=null&&haversineKm({lat:d.lat,lng:d.lng},{lat:u.lat,lng:u.lng})<=30)notify(u.id,'Emergency food rescue',`${d.title} expires ${new Date(d.expires_at).toLocaleString()} near ${d.address}.`,`/donations/${d.id}`,`emergency-${d.id}-${u.id}`);for(const u of db.prepare("SELECT id FROM users WHERE role='ADMIN' AND status='ACTIVE'").all() as {id:number}[])notify(u.id,'Emergency rescue needs attention',`${d.title} expires soon near ${d.address}.`,`/donations/${d.id}`,`emergency-${d.id}-${u.id}`);}}
function enc(value:string){const key=crypto.scryptSync(process.env.SESSION_SECRET??'smartfood-local-dev-secret-change-me','smartfood-verification',32),iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',key,iv),data=Buffer.concat([cipher.update(value,'utf8'),cipher.final()]);return `${iv.toString('hex')}.${cipher.getAuthTag().toString('hex')}.${data.toString('hex')}`;}
function dec(value:string){const [i,t,d]=value.split('.'),key=crypto.scryptSync(process.env.SESSION_SECRET??'smartfood-local-dev-secret-change-me','smartfood-verification',32),decipher=crypto.createDecipheriv('aes-256-gcm',key,Buffer.from(i,'hex'));decipher.setAuthTag(Buffer.from(t,'hex'));return Buffer.concat([decipher.update(Buffer.from(d,'hex')),decipher.final()]).toString('utf8');}
function secretHash(value:string){return crypto.createHash('sha256').update(`${process.env.SESSION_SECRET??'smartfood-local-dev-secret-change-me'}:${value}`).digest('hex');}
const uploadDir=path.resolve(process.env.UPLOAD_DIR??'./data/uploads');fs.mkdirSync(uploadDir,{recursive:true});
function storeImage(dataUrl?:string){if(!dataUrl)return null;const match=/^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$/.exec(dataUrl);if(!match)throw Object.assign(new Error('Upload a JPG, PNG, or WEBP image.'),{status:400});const buffer=Buffer.from(match[2],'base64');if(buffer.length>5*1024*1024)throw Object.assign(new Error('Images must be smaller than 5 MB.'),{status:413});const type=match[1],valid=type==='jpeg'?buffer[0]===0xff&&buffer[1]===0xd8&&buffer[2]===0xff:type==='png'?buffer.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):buffer.subarray(0,4).toString()==='RIFF'&&buffer.subarray(8,12).toString()==='WEBP';if(!valid)throw Object.assign(new Error('The image content does not match its file type.'),{status:400});const name=`${crypto.randomUUID()}.${type==='jpeg'?'jpg':type}`,filename=path.basename(name);fs.writeFileSync(path.join(uploadDir,filename),buffer,{flag:'wx'});return filename;}
function makeVerification(donationId:number,assignmentId:number,stage:'PICKUP'|'DELIVERY'){const token=crypto.randomBytes(32).toString('base64url'),code=String(crypto.randomInt(0,100000000)).padStart(8,'0');db.prepare('INSERT INTO verifications(donation_id,assignment_id,stage,token_hash,code_hash,expires_at,token_encrypted,code_encrypted) VALUES(?,?,?,?,?,?,?,?)').run(donationId,assignmentId,stage,secretHash(token),secretHash(code),new Date(Date.now()+2*3600000).toISOString(),enc(token),enc(code));return {token,code};}
function issueAssignment(donationId:number,claimId:number,exclude:number[]=[]){const d=db.prepare('SELECT lat,lng FROM donations WHERE id=?').get(donationId) as any,claim=db.prepare('SELECT ngo_id,quantity FROM claims WHERE id=?').get(claimId) as any;if(!d||!claim)return null;const ngo=db.prepare('SELECT lat,lng FROM users WHERE id=?').get(claim.ngo_id) as any;if(!ngo)return null;const volunteers=db.prepare("SELECT u.*, (SELECT COUNT(*) FROM assignments a WHERE a.volunteer_id=u.id AND a.status IN ('OFFERED','ACCEPTED','PICKUP_STARTED','PICKED_UP','IN_TRANSIT')) workload,(SELECT AVG(r.stars) FROM ratings r WHERE r.rated_id=u.id) rating,(SELECT COUNT(*) FROM assignments a WHERE a.volunteer_id=u.id AND a.status='COMPLETED') completed,(SELECT COUNT(*) FROM assignments a WHERE a.volunteer_id=u.id AND a.status='CANCELLED') cancelled FROM users u WHERE u.role='VOLUNTEER' AND u.status='ACTIVE' AND u.available=1 AND u.capacity>=? ORDER BY u.id").all(claim.quantity) as any[];const eligible=volunteers.map(v=>{if(v.lat==null||v.lng==null)return null;const donorDistance=haversineKm({lat:d.lat,lng:d.lng},{lat:v.lat,lng:v.lng}),ngoDistance=haversineKm({lat:ngo.lat,lng:ngo.lng},{lat:v.lat,lng:v.lng});if(donorDistance>30||ngoDistance>30)return null;const reliability=reliabilityScore(v.rating==null?[]:[v.rating],v.completed,v.cancelled);return {...v,score:volunteerScore({donorDistance:100-donorDistance/30*100,ngoDistance:100-ngoDistance/30*100,capacity:Math.min(100,v.capacity/claim.quantity*100),workload:Math.max(0,100-v.workload*25),availability:100,reliability})};}).filter(Boolean).filter(v=>!exclude.includes((v as any).id)).sort((a:any,b:any)=>b.score-a.score);if(!eligible.length)return null;const v=eligible[0] as any,r=db.prepare("INSERT INTO assignments(donation_id,claim_id,volunteer_id,status) VALUES(?,?,?,'OFFERED')").run(donationId,claimId,v.id),assignmentId=Number(r.lastInsertRowid);db.prepare("UPDATE donations SET status='VOLUNTEER_ASSIGNED' WHERE id=?").run(donationId);const secrets=makeVerification(donationId,assignmentId,'PICKUP');notify(v.id,'Rescue assignment offered','A food rescue near you is ready for review.','/assignments',`assign-${assignmentId}`);event(donationId,'VOLUNTEER_ASSIGNED',null,`Assignment offered to ${v.name}.`);return {assignmentId,volunteer:v,secrets};}
const loginLimiter=rateLimit({windowMs:15*60*1000,max:process.env.NODE_ENV==='test'?100:10,standardHeaders:true,legacyHeaders:false,message:{error:'Too many sign-in attempts. Try again later.'}});
app.get('/api/health',(_req,res)=>res.json({ok:true}));
