app.post('/api/auth/register', async(req,res)=>{ const schema=z.object({name:z.string().trim().min(2).max(80),email:z.string().email().max(200),password:z.string().min(8).max(100),role:z.enum(['DONOR','NGO','VOLUNTEER']),address:z.string().trim().max(250).optional()}); const parsed=schema.safeParse(req.body); if(!parsed.success)return res.status(400).json({error:parsed.error.issues[0]?.message??'Check your details.'}); const d=parsed.data; try { const result=db.prepare('INSERT INTO users(email,password_hash,role,name,address,verified) VALUES(?,?,?,?,?,?)').run(d.email,d.password && await bcrypt.hash(d.password,12),d.role,d.name,d.address??null,d.role==='NGO'?0:1); const id=Number(result.lastInsertRowid); if(d.role==='NGO')db.prepare('INSERT INTO ngo_applications(user_id) VALUES(?)').run(id); audit(id,'REGISTER','user',id); await new Promise<void>((resolve,reject)=>req.session.regenerate(e=>e?reject(e):resolve())); req.session.userId=id; req.session.csrf=crypto.randomBytes(24).toString('hex'); res.status(201).json({user:userQuery.get(id),csrf:req.session.csrf,pending:d.role==='NGO'}); } catch(e){ if(String(e).includes('UNIQUE'))return res.status(409).json({error:'An account with this email already exists.'}); throw e; }});
app.post('/api/auth/login',loginLimiter, async(req,res)=>{ const p=z.object({email:z.string().email(),password:z.string().min(1)}).safeParse(req.body); if(!p.success)return res.status(400).json({error:'Enter a valid email and password.'}); const row=db.prepare('SELECT id,password_hash FROM users WHERE email=? COLLATE NOCASE').get(p.data.email) as {id:number,password_hash:string}|undefined; if(!row||!await bcrypt.compare(p.data.password,row.password_hash)){audit(row?.id??null,'LOGIN_FAILED','user',row?.id);return res.status(401).json({error:'Email or password is incorrect.'});} const u=userQuery.get(row.id) as User; if(u.status!=='ACTIVE')return res.status(403).json({error:'This account is suspended. Contact the platform administrator.'}); await new Promise<void>((resolve,reject)=>req.session.regenerate(e=>e?reject(e):resolve())); req.session.userId=u.id; req.session.csrf=crypto.randomBytes(24).toString('hex'); audit(u.id,'LOGIN','user',u.id); res.json({user:u,csrf:req.session.csrf}); });
app.post('/api/auth/logout',auth,csrf,(req,res)=>{const id=req.session.userId??null;req.session.destroy(()=>res.json({ok:true}));audit(id,'LOGOUT','user',id??undefined);});
app.use('/api', (req,res,next)=>req.path.startsWith('/auth/')||req.path==='/session'||req.path==='/health'||req.path==='/summary'?next():auth(req,res,next));
app.use('/api',csrf);
