app.get('/api/uploads/:filename',(req,res)=>{const filename=path.basename(req.params.filename);if(filename!==req.params.filename)return res.status(404).end();const d=db.prepare('SELECT id,donor_id FROM donations WHERE photo_path=? UNION SELECT d.id,d.donor_id FROM deliveries x JOIN donations d ON d.id=x.donation_id WHERE x.photo_path=? LIMIT 1').get(filename,filename) as any;if(!d)return res.status(404).end();const u=res.locals.user as User,allowed=u.role==='ADMIN'||u.role==='DONOR'&&u.id===d.donor_id||u.role==='NGO'&&Boolean(db.prepare("SELECT 1 FROM claims WHERE donation_id=? AND ngo_id=? AND status='APPROVED'").get(d.id,u.id))||u.role==='VOLUNTEER'&&Boolean(db.prepare('SELECT 1 FROM assignments WHERE donation_id=? AND volunteer_id=?').get(d.id,u.id));if(!allowed)return res.status(404).end();res.sendFile(path.join(uploadDir,filename));});
app.get('/api/categories',(_req,res)=>res.json(db.prepare('SELECT id,name,icon FROM categories ORDER BY name').all()));
app.post('/api/classify',roles('DONOR'),(req,res)=>{const p=z.object({title:z.string().max(120),description:z.string().max(1000).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Enter a title before asking for a suggestion.'});const text=`${p.data.title} ${p.data.description??''}`.toLowerCase(),rules:[string,string[]][]=[['Cooked Meals',['meal','lunch','dinner','idli','dosa','rice bowl','cooked','sambar','biryani']],['Bread',['bread','loaf','toast']],['Bakery',['cake','bun','pastry','bakery','croissant']],['Dairy',['milk','curd','yogurt','cheese','paneer']],['Fruits',['fruit','banana','apple','mango','guava']],['Vegetables',['vegetable','greens','spinach','tomato','potato']],['Beverages',['juice','drink','beverage','tea','coffee']],['Packaged Food',['pack','canned','sealed','snack']]];const found=rules.find(([,keywords])=>keywords.some(k=>text.includes(k)));res.json({category:found?.[0]??'Other',categoryId:(db.prepare('SELECT id FROM categories WHERE name=?').get(found?.[0]??'Other') as any)?.id,notice:'Suggestion only — please check it yourself.',basis:'Based on the entered title and description. The photograph is not analysed.'});});
app.post('/api/admin/categories',roles('ADMIN'),(req,res)=>{const p=z.object({name:z.string().trim().min(2).max(60),icon:z.string().trim().max(12).default('🍲')}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Enter a category name.'});try{const r=db.prepare('INSERT INTO categories(name,icon) VALUES(?,?)').run(p.data.name,p.data.icon);audit((res.locals.user as User).id,'CATEGORY_CREATED','category',Number(r.lastInsertRowid));res.status(201).json({id:Number(r.lastInsertRowid)});}catch{return res.status(409).json({error:'That category already exists.'});}});
app.patch('/api/admin/categories/:id',roles('ADMIN'),(req,res)=>{const p=z.object({name:z.string().trim().min(2).max(60).optional(),icon:z.string().trim().max(12).optional()}).safeParse(req.body);if(!p.success||!Object.keys(p.data).length)return res.status(400).json({error:'Enter a valid category change.'});const c=db.prepare('SELECT * FROM categories WHERE id=?').get(Number(req.params.id)) as any;if(!c)return res.status(404).json({error:'Category not found.'});db.prepare('UPDATE categories SET name=?,icon=? WHERE id=?').run(p.data.name??c.name,p.data.icon??c.icon,c.id);audit((res.locals.user as User).id,'CATEGORY_UPDATED','category',c.id);res.json({ok:true});});
app.delete('/api/admin/categories/:id',roles('ADMIN'),(req,res)=>{try{const result=db.prepare('DELETE FROM categories WHERE id=?').run(Number(req.params.id));if(!result.changes)return res.status(404).json({error:'Category not found.'});audit((res.locals.user as User).id,'CATEGORY_DELETED','category',Number(req.params.id));res.json({ok:true});}catch{return res.status(409).json({error:'This category is used by existing food records and cannot be removed.'});}});
