app.post('/api/notifications/read-all',(req,res)=>{db.prepare('UPDATE notifications SET read_at=CURRENT_TIMESTAMP WHERE user_id=? AND read_at IS NULL').run((res.locals.user as User).id);res.json({ok:true});});
