app.get('/api/donations',(req,res)=>{runMaintenance();const u=res.locals.user as User,p=z.object({page:z.coerce.number().int().min(1).default(1),limit:z.coerce.number().int().min(1).max(50).default(20)}).safeParse(req.query);if(!p.success)return res.status(400).json({error:'Invalid pagination.'});const {page,limit}=p.data,offset=(page-1)*limit;let where='',args:unknown[]=[];if(u.role==='DONOR'){where='WHERE d.donor_id=?';args=[u.id];}else if(u.role==='NGO'){where="WHERE d.status='AVAILABLE' AND d.expires_at>? AND d.available_quantity>0";args=[new Date().toISOString()];}else if(u.role==='VOLUNTEER'){where='WHERE EXISTS(SELECT 1 FROM assignments a WHERE a.donation_id=d.id AND a.volunteer_id=?)';args=[u.id];}const total=(db.prepare(`SELECT COUNT(*) n FROM donations d ${where}`).get(...args) as any).n,rows=db.prepare(`SELECT d.*,c.name category,c.icon FROM donations d JOIN categories c ON c.id=d.category_id ${where} ORDER BY d.expires_at LIMIT ? OFFSET ?`).all(...args,limit,offset) as any[],items=rows.map(d=>{const f=freshness(d.prepared_at,d.expires_at,new Date(),d.category),uScore=urgency(d.expires_at);return {...d,freshness:f,urgency:uScore,priority:priority(uScore.score,f,d.available_quantity,['Cooked Meals','Dairy'].includes(d.category))};});res.json({items,page,limit,total});});
app.post('/api/donations',roles('DONOR'),(req,res)=>{const schema=z.object({title:z.string().trim().min(3).max(120),description:z.string().max(1000).default(''),categoryId:z.number().int().positive(),quantity:z.number().positive().max(100000),unit:z.string().min(1).max(30),preparedAt:z.string().datetime(),expiresAt:z.string().datetime(),address:z.string().min(3).max(250),lat:z.number().min(-90).max(90),lng:z.number().min(-180).max(180),safetyAck:z.literal(true),photoData:z.string().max(7_000_000).optional(),items:z.array(z.object({name:z.string().min(1),quantity:z.number().positive(),unit:z.string().min(1)})).min(1)});const p=schema.safeParse(req.body);if(!p.success)return res.status(400).json({error:p.error.issues[0]?.message??'Check donation details.'});const d=p.data,now=Date.now();if(Date.parse(d.expiresAt)<=now||Date.parse(d.preparedAt)>now)return res.status(400).json({error:'Preparation and expiry times must be valid and expiry must be in the future.'});const cat=db.prepare('SELECT 1 FROM categories WHERE id=?').get(d.categoryId);if(!cat)return res.status(400).json({error:'Choose a valid food category.'});const photoPath=storeImage(d.photoData);const u=res.locals.user as User;const id=db.transaction(()=>{const x=db.prepare('INSERT INTO donations(donor_id,title,description,category_id,quantity,available_quantity,unit,prepared_at,expires_at,address,lat,lng,safety_ack,photo_path) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1,?)').run(u.id,d.title,d.description,d.categoryId,d.quantity,d.quantity,d.unit,d.preparedAt,d.expiresAt,d.address,d.lat,d.lng,photoPath);const donationId=Number(x.lastInsertRowid);for(const item of d.items)db.prepare('INSERT INTO food_items(donation_id,name,category_id,quantity,unit) VALUES(?,?,?,?,?)').run(donationId,item.name,d.categoryId,item.quantity,item.unit);event(donationId,'DONATION_CREATED',u.id,`${d.quantity} ${d.unit} available`);audit(u.id,'DONATION_CREATED','donation',donationId);return donationId;})();res.status(201).json(db.prepare('SELECT * FROM donations WHERE id=?').get(id));});
