app.get('/api/admin/users',roles('ADMIN'),(req,res)=>{const page=Math.max(1,Number(req.query.page)||1),limit=Math.min(50,Math.max(1,Number(req.query.limit)||20)),q=typeof req.query.q==='string'?req.query.q.trim().slice(0,100):'';const filter=q?'WHERE name LIKE ? OR email LIKE ?':'',args=q?[`%${q}%`,`%${q}%`,limit,(page-1)*limit]:[limit,(page-1)*limit];const count=db.prepare(`SELECT COUNT(*) n FROM users ${filter}`).get(...(q?[`%${q}%`,`%${q}%`]:[])) as {n:number};res.json({items:db.prepare(`SELECT id,email,role,name,status,verified,created_at FROM users ${filter} ORDER BY id LIMIT ? OFFSET ?`).all(...args),page,limit,total:count.n});});
