app.get('/api/donations/:id/scores',(req,res)=>{const id=Number(req.params.id),d=db.prepare('SELECT d.*,c.name category FROM donations d JOIN categories c ON c.id=d.category_id WHERE d.id=?').get(id) as any;if(!d)return res.status(404).json({error:'Donation not found.'});const u=res.locals.user as User;if(u.role==='DONOR'&&d.donor_id!==u.id||u.role==='NGO'&&d.status!=='AVAILABLE'&&!db.prepare('SELECT 1 FROM claims WHERE donation_id=? AND ngo_id=?').get(id,u.id)||u.role==='VOLUNTEER'&&!db.prepare('SELECT 1 FROM assignments WHERE donation_id=? AND volunteer_id=?').get(id,u.id))return res.status(404).json({error:'Donation not found.'});if(expireDonation(id,u.id))d.status='EXPIRED';const f=freshness(d.prepared_at,d.expires_at,new Date(),d.category),uScore=urgency(d.expires_at);res.json({freshness:f,urgency:uScore,priority:priority(uScore.score,f,d.available_quantity,['Cooked Meals','Dairy'].includes(d.category)),explanation:`${uScore.band.toLowerCase().replace('_',' ')} urgency · ${d.category} freshness profile`});});
app.post('/api/claims',(req,res)=>{const u=res.locals.user as User;if(u.role!=='NGO')return res.status(403).json({error:'Only community NGOs can request food.'});if(!u.verified)return res.status(403).json({error:'Your NGO must be verified before requesting food.'});const p=z.object({donationId:z.number().int().positive(),quantity:z.number().positive().max(100000)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Enter a valid requested quantity.'});const id=p.data.donationId;expireDonation(id,u.id);const d=db.prepare('SELECT * FROM donations WHERE id=?').get(id) as any;if(!d||d.status!=='AVAILABLE'||d.expires_at<=new Date().toISOString())return res.status(409).json({error:'This donation is no longer available.'});if(p.data.quantity>d.available_quantity)return res.status(409).json({error:'Requested quantity exceeds current availability.'});const r=db.prepare("INSERT INTO claims(donation_id,ngo_id,quantity,status) VALUES(?,?,?,'PENDING')").run(id,u.id,p.data.quantity);event(id,'CLAIM_REQUESTED',u.id,`${p.data.quantity} ${d.unit} requested`);notify(d.donor_id,'A community requested your donation',`${u.name} requested ${p.data.quantity} ${d.unit}.`,`/donations/${id}`,`claim-${r.lastInsertRowid}`);audit(u.id,'CLAIM_CREATED','claim',Number(r.lastInsertRowid));res.status(201).json({id:Number(r.lastInsertRowid),status:'PENDING'});});
app.get('/api/claims',(req,res)=>{const u=res.locals.user as User;const where=u.role==='ADMIN'?'':'WHERE '+(u.role==='DONOR'?'d.donor_id=?':'c.ngo_id=?');const args=u.role==='ADMIN'?[]:[u.id];res.json(db.prepare(`SELECT c.*,d.title,d.unit,d.donor_id,d.status donation_status,(SELECT id FROM assignments WHERE claim_id=c.id ORDER BY id DESC LIMIT 1) assignment_id,(SELECT volunteer_id FROM assignments WHERE claim_id=c.id ORDER BY id DESC LIMIT 1) volunteer_id,u.name ngo_name FROM claims c JOIN donations d ON d.id=c.donation_id JOIN users u ON u.id=c.ngo_id ${where} ORDER BY c.id DESC LIMIT 100`).all(...args));});
app.post('/api/claims/:id/decision',roles('DONOR'),(req,res)=>{const p=z.object({decision:z.enum(['APPROVED','REJECTED']),reason:z.string().max(500).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Choose approve or reject.'});const claimId=Number(req.params.id),actor=res.locals.user as User;const result=db.transaction(()=>{const c=db.prepare('SELECT c.*,d.donor_id,d.available_quantity,d.status donation_status,d.expires_at,d.unit FROM claims c JOIN donations d ON d.id=c.donation_id WHERE c.id=?').get(claimId) as any;if(!c||c.donor_id!==actor.id)return {error:'Claim not found.',status:404};if(c.status!=='PENDING')return {error:'This claim has already been decided.',status:409};if(p.data.decision==='REJECTED'){db.prepare("UPDATE claims SET status='REJECTED',reason=? WHERE id=?").run(p.data.reason??'Not available for this request.',claimId);event(c.donation_id,'CLAIM_REJECTED',actor.id,p.data.reason);audit(actor.id,'CLAIM_REJECTED','claim',claimId);notify(c.ngo_id,'Claim not approved',p.data.reason??'The donor could not approve this request.',`/claims`,`claim-rejected-${claimId}`);return {claimId,status:'REJECTED'};}const current=db.prepare('SELECT available_quantity,status,expires_at FROM donations WHERE id=?').get(c.donation_id) as any;if(current.status!=='AVAILABLE'||current.expires_at<=new Date().toISOString()||current.available_quantity<c.quantity){db.prepare("UPDATE claims SET status='REJECTED',reason='Insufficient remaining quantity or donation no longer available.' WHERE id=?").run(claimId);return {error:'Insufficient remaining quantity; this request was declined.',status:409};}db.prepare("UPDATE claims SET status='APPROVED' WHERE id=?").run(claimId);db.prepare("UPDATE donations SET available_quantity=available_quantity-?,claimed_quantity=claimed_quantity+?,reserved_quantity=reserved_quantity+?,status='CLAIMED' WHERE id=?").run(c.quantity,c.quantity,c.quantity,c.donation_id);event(c.donation_id,'CLAIM_APPROVED',actor.id,`${c.quantity} ${c.unit} reserved`);audit(actor.id,'CLAIM_APPROVED','claim',claimId);notify(c.ngo_id,'Your food claim was approved',`${c.quantity} ${c.unit} are reserved for your organisation.`,`/claims`,`claim-approved-${claimId}`);const assignment=issueAssignment(c.donation_id,claimId);return {claimId,status:'APPROVED',assignmentOffered:Boolean(assignment),message:assignment?'A volunteer has been offered the rescue.':'No volunteer is currently eligible; an administrator can assign one.'};}).immediate();if('error'in result)return res.status(result.status as number).json({error:result.error});res.json(result);});
app.get('/api/donations/:id/pickup-code',roles('DONOR'),async(req,res)=>{const id=Number(req.params.id),u=res.locals.user as User,d=db.prepare('SELECT donor_id FROM donations WHERE id=?').get(id) as any;if(!d||d.donor_id!==u.id)return res.status(404).json({error:'Donation not found.'});const v=db.prepare("SELECT token_encrypted,code_encrypted,expires_at FROM verifications WHERE donation_id=? AND stage='PICKUP' AND used_at IS NULL ORDER BY id DESC LIMIT 1").get(id) as any;if(!v)return res.status(404).json({error:'Pickup verification has not been issued.'});const token=dec(v.token_encrypted);res.json({token,code:dec(v.code_encrypted),expiresAt:v.expires_at,qrDataUrl:await QRCode.toDataURL(token,{width:180,margin:1})});});
app.get('/api/assignments',roles('VOLUNTEER','ADMIN'),(req,res)=>{const u=res.locals.user as User;res.json(db.prepare(`SELECT a.*,d.title,d.description,d.address pickup_address,d.lat pickup_lat,d.lng pickup_lng,d.expires_at,c.quantity,c.ngo_id,ngo.name ngo_name,ngo.address ngo_address,ngo.lat ngo_lat,ngo.lng ngo_lng FROM assignments a JOIN donations d ON d.id=a.donation_id JOIN claims c ON c.id=a.claim_id JOIN users ngo ON ngo.id=c.ngo_id ${u.role==='ADMIN'?'':'WHERE a.volunteer_id=?'} ORDER BY a.id DESC LIMIT 100`).all(...(u.role==='ADMIN'?[]:[u.id])));});
app.post('/api/admin/assignments',roles('ADMIN'),(req,res)=>{const p=z.object({donationId:z.number().int().positive(),volunteerId:z.number().int().positive()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Choose a donation and volunteer.'});const d=db.prepare("SELECT d.*,c.id claim_id,c.quantity FROM donations d JOIN claims c ON c.donation_id=d.id AND c.status='APPROVED' WHERE d.id=?").get(p.data.donationId) as any,v=db.prepare("SELECT * FROM users WHERE id=? AND role='VOLUNTEER' AND status='ACTIVE' AND available=1").get(p.data.volunteerId) as any;if(!d||d.status!=='CLAIMED')return res.status(409).json({error:'Only a claimed rescue without an active assignment can be assigned.'});if(!v||v.capacity<d.quantity||v.lat==null||haversineKm({lat:d.lat,lng:d.lng},{lat:v.lat,lng:v.lng})>30)return res.status(400).json({error:'Volunteer is unavailable, too far away, or lacks capacity.'});try{const r=db.prepare("INSERT INTO assignments(donation_id,claim_id,volunteer_id,status) VALUES(?,?,?,'OFFERED')").run(d.id,d.claim_id,v.id);db.prepare("UPDATE donations SET status='VOLUNTEER_ASSIGNED' WHERE id=?").run(d.id);makeVerification(d.id,Number(r.lastInsertRowid),'PICKUP');notify(v.id,'Rescue assignment offered','An administrator assigned a nearby rescue for your review.','/assignments',`admin-assign-${r.lastInsertRowid}`);event(d.id,'ADMIN_ASSIGNED', (res.locals.user as User).id,`Offered to ${v.name}.`);audit((res.locals.user as User).id,'VOLUNTEER_ASSIGNED_MANUALLY','assignment',Number(r.lastInsertRowid));res.status(201).json({id:Number(r.lastInsertRowid)});}catch{return res.status(409).json({error:'Another volunteer already has an active assignment for this rescue.'});}});
app.post('/api/assignments/:id/respond',roles('VOLUNTEER'),(req,res)=>{const p=z.object({accept:z.boolean()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Choose accept or reject.'});const a=db.prepare('SELECT * FROM assignments WHERE id=?').get(Number(req.params.id)) as any,u=res.locals.user as User;if(!a||a.volunteer_id!==u.id||a.status!=='OFFERED')return res.status(404).json({error:'Assignment not found.'});if(p.data.accept){db.prepare("UPDATE assignments SET status='ACCEPTED' WHERE id=? AND status='OFFERED'").run(a.id);event(a.donation_id,'VOLUNTEER_ACCEPTED',u.id,`${u.name} accepted the rescue`);return res.json({status:'ACCEPTED'});}db.transaction(()=>{db.prepare("UPDATE assignments SET status='REJECTED' WHERE id=?").run(a.id);const excluded=(db.prepare('SELECT volunteer_id FROM assignments WHERE donation_id=?').all(a.donation_id) as {volunteer_id:number}[]).map(v=>v.volunteer_id);db.prepare("UPDATE donations SET status='CLAIMED' WHERE id=?").run(a.donation_id);const next=issueAssignment(a.donation_id,a.claim_id,excluded);event(a.donation_id,'VOLUNTEER_REJECTED',u.id,`${u.name} declined the assignment.`);if(!next)event(a.donation_id,'ASSIGNMENT_UNFILLED',u.id,'No eligible volunteer accepted the rescue.');})();res.json({status:'REJECTED'});});
app.post('/api/assignments/:id/pickup/start',roles('VOLUNTEER'),(req,res)=>{const a=db.prepare('SELECT * FROM assignments WHERE id=?').get(Number(req.params.id)) as any,u=res.locals.user as User;if(a)expireDonation(a.donation_id,u.id);if(!a||a.volunteer_id!==u.id||a.status!=='ACCEPTED')return res.status(409).json({error:'Accept the assignment and confirm the donation has not expired before starting pickup.'});db.prepare("UPDATE assignments SET status='PICKUP_STARTED' WHERE id=?").run(a.id);db.prepare("UPDATE donations SET status='PICKUP_STARTED' WHERE id=?").run(a.donation_id);event(a.donation_id,'PICKUP_STARTED',u.id);res.json({status:'PICKUP_STARTED',notice:'Food safety must be verified by the donor and the receiving organisation.'});});
app.post('/api/assignments/:id/verify',(req,res)=>{const p=z.object({stage:z.enum(['PICKUP','DELIVERY']),value:z.string().min(8).max(200)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Enter a valid verification code.'});const a=db.prepare('SELECT * FROM assignments WHERE id=?').get(Number(req.params.id)) as any,u=res.locals.user as User;if(!a||a.volunteer_id!==u.id)return res.status(404).json({error:'Assignment not found.'});if(expireDonation(a.donation_id,u.id))return res.status(409).json({error:'This donation expired and can no longer be verified.'});if(p.data.stage==='PICKUP'&&a.status!=='PICKUP_STARTED'||p.data.stage==='DELIVERY'&&a.status!=='IN_TRANSIT')return res.status(409).json({error:'This verification is out of sequence.'});const v=db.prepare('SELECT * FROM verifications WHERE assignment_id=? AND stage=? AND used_at IS NULL ORDER BY id DESC LIMIT 1').get(a.id,p.data.stage) as any;if(!v)return res.status(409).json({error:'Verification is unavailable or already used.'});if(v.expires_at<=new Date().toISOString())return res.status(410).json({error:'Verification expired. Ask the donor or receiving organisation to refresh it.'});const submitted=secretHash(p.data.value);if(v.attempts>=5)return res.status(429).json({error:'Too many attempts. Contact the donor or receiving organisation.'});if(submitted!==v.token_hash&&submitted!==v.code_hash){db.prepare('UPDATE verifications SET attempts=attempts+1 WHERE id=?').run(v.id);return res.status(400).json({error:'Code did not match. Check the stage and try again.'});}db.prepare('UPDATE verifications SET used_at=CURRENT_TIMESTAMP WHERE id=? AND used_at IS NULL').run(v.id);if(p.data.stage==='PICKUP'){db.prepare("UPDATE assignments SET status='PICKED_UP' WHERE id=?").run(a.id);db.prepare("UPDATE donations SET status='PICKED_UP' WHERE id=?").run(a.donation_id);event(a.donation_id,'PICKED_UP',u.id);}else{db.prepare("UPDATE assignments SET status='DELIVERED' WHERE id=?").run(a.id);db.prepare("UPDATE donations SET status='DELIVERED' WHERE id=?").run(a.donation_id);event(a.donation_id,'DELIVERY_VERIFIED',u.id);}audit(u.id,`${p.data.stage}_VERIFIED`,'donation',a.donation_id);res.json({verified:true,status:p.data.stage==='PICKUP'?'PICKED_UP':'DELIVERED'});});
app.post('/api/assignments/:id/delivery/start',roles('VOLUNTEER'),(req,res)=>{const a=db.prepare('SELECT * FROM assignments WHERE id=?').get(Number(req.params.id)) as any,u=res.locals.user as User;if(a)expireDonation(a.donation_id,u.id);if(!a||a.volunteer_id!==u.id||a.status!=='PICKED_UP')return res.status(409).json({error:'Verify pickup and confirm the donation is still in date before starting delivery.'});db.prepare("UPDATE assignments SET status='IN_TRANSIT' WHERE id=?").run(a.id);db.prepare("UPDATE donations SET status='IN_TRANSIT' WHERE id=?").run(a.donation_id);event(a.donation_id,'IN_TRANSIT',u.id);makeVerification(a.donation_id,a.id,'DELIVERY');notify(a.volunteer_id,'Delivery started','Ask the receiving organisation for its arrival code.','/assignments',`delivery-code-${a.id}`);res.json({status:'IN_TRANSIT'});});
app.get('/api/assignments/:id/delivery-code',roles('NGO'),async(req,res)=>{const a=db.prepare('SELECT a.*,c.ngo_id FROM assignments a JOIN claims c ON c.id=a.claim_id WHERE a.id=?').get(Number(req.params.id)) as any,u=res.locals.user as User;if(!a||a.ngo_id!==u.id||a.status!=='IN_TRANSIT')return res.status(404).json({error:'Delivery verification is not available.'});const v=db.prepare("SELECT token_encrypted,code_encrypted,expires_at FROM verifications WHERE assignment_id=? AND stage='DELIVERY' AND used_at IS NULL ORDER BY id DESC LIMIT 1").get(a.id) as any;if(!v)return res.status(404).json({error:'Delivery code is unavailable.'});const token=dec(v.token_encrypted);res.json({token,code:dec(v.code_encrypted),expiresAt:v.expires_at,qrDataUrl:await QRCode.toDataURL(token,{width:180,margin:1})});});
app.post('/api/assignments/:id/delivery',(req,res)=>{const p=z.object({deliveredQuantity:z.number().positive(),recipientName:z.string().trim().min(2).max(100),photoData:z.string().max(7_000_000).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Enter a valid delivered quantity and recipient.'});const a=db.prepare('SELECT a.*,c.quantity expected,d.status FROM assignments a JOIN claims c ON c.id=a.claim_id JOIN donations d ON d.id=a.donation_id WHERE a.id=?').get(Number(req.params.id)) as any,u=res.locals.user as User;if(!a||a.volunteer_id!==u.id||a.status!=='DELIVERED')return res.status(409).json({error:'Verify NGO arrival before submitting delivery.'});if(expireDonation(a.donation_id,u.id))return res.status(409).json({error:'This donation expired; delivery cannot be completed.'});const photoPath=storeImage(p.data.photoData),discrepancy=p.data.deliveredQuantity-a.expected;db.transaction(()=>{db.prepare('INSERT INTO deliveries(donation_id,assignment_id,expected_quantity,delivered_quantity,recipient_name,photo_path) VALUES(?,?,?,?,?,?)').run(a.donation_id,a.id,a.expected,p.data.deliveredQuantity,p.data.recipientName,photoPath);db.prepare('UPDATE donations SET delivered_quantity=? WHERE id=?').run(p.data.deliveredQuantity,a.donation_id);event(a.donation_id,'DELIVERY_SUBMITTED',u.id,`Delivered ${p.data.deliveredQuantity}; approved ${a.expected}; discrepancy ${discrepancy>=0?'+':''}${discrepancy}`);notify(a.ngo_id,'Food delivery is ready for review','Please confirm the quantity received.','/claims',`delivery-${a.id}`);audit(u.id,'DELIVERY_SUBMITTED','donation',a.donation_id);})();res.status(201).json({discrepancy,display:`${discrepancy>0?'+':''}${discrepancy} ${a.unit??'meals'}`});});
app.post('/api/donations/:id/receipt',(req,res)=>{const p=z.object({receivedQuantity:z.number().positive(),receivedBy:z.string().trim().min(2).max(100),safetyAck:z.literal(true)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Receipt acknowledgement and valid quantity are required.'});const id=Number(req.params.id),u=res.locals.user as User;expireDonation(id,u.id);const d=db.prepare('SELECT d.*,c.ngo_id FROM donations d JOIN claims c ON c.donation_id=d.id AND c.status=\'APPROVED\' WHERE d.id=?').get(id) as any;if(!d||d.ngo_id!==u.id||d.status!=='DELIVERED')return res.status(404).json({error:'Delivery is not available for your organisation to confirm.'});const delivered=db.prepare('SELECT * FROM deliveries WHERE donation_id=?').get(id) as any;if(!delivered)return res.status(409).json({error:'Volunteer delivery proof is required first.'});db.transaction(()=>{db.prepare('INSERT INTO receipts(donation_id,ngo_id,received_quantity,safety_ack,received_by) VALUES(?,?,?,1,?)').run(id,u.id,p.data.receivedQuantity,p.data.receivedBy);db.prepare("UPDATE deliveries SET received_quantity=?,accepted=1 WHERE id=?").run(p.data.receivedQuantity,delivered.id);db.prepare("UPDATE donations SET status='RECEIVED' WHERE id=?").run(id);db.prepare("UPDATE assignments SET status='COMPLETED' WHERE donation_id=?").run(id);event(id,'RECEIVED',u.id,`Received ${p.data.receivedQuantity}; delivered ${delivered.delivered_quantity}; approved ${delivered.expected_quantity}.`);notify(d.donor_id,'Your rescue was received','The receiving organisation confirmed receipt.','/impact',`received-${id}`);audit(u.id,'RECEIPT_CONFIRMED','donation',id);})();res.json({status:'RECEIVED',impact:estimatedImpact(p.data.receivedQuantity,.4,2.5,p.data.receivedQuantity)});});
app.post('/api/donations/:id/ratings',auth,(req,res)=>{const p=z.object({ratedUserId:z.number().int().positive(),stars:z.number().int().min(1).max(5)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Choose a person and a rating from one to five stars.'});const id=Number(req.params.id),u=res.locals.user as User;if(!db.prepare('SELECT 1 FROM receipts WHERE donation_id=?').get(id))return res.status(409).json({error:'Ratings are available after a confirmed receipt.'});const people=db.prepare('SELECT donor_id user_id FROM donations WHERE id=? UNION SELECT ngo_id FROM receipts WHERE donation_id=? UNION SELECT volunteer_id FROM assignments WHERE donation_id=? AND status=\'COMPLETED\'').all(id,id,id) as {user_id:number}[];if(!people.some(x=>x.user_id===u.id)||!people.some(x=>x.user_id===p.data.ratedUserId)||p.data.ratedUserId===u.id)return res.status(403).json({error:'Only people involved in this completed rescue can rate each other.'});try{db.prepare('INSERT INTO ratings(donation_id,rater_id,rated_id,stars) VALUES(?,?,?,?)').run(id,u.id,p.data.ratedUserId,p.data.stars);audit(u.id,'RESCUE_RATED','rating',id);res.status(201).json({ok:true});}catch{return res.status(409).json({error:'You have already rated this person for this rescue.'});}});
app.get('/api/admin/overview',roles('ADMIN'),(_req,res)=>res.json({users:db.prepare('SELECT COUNT(*) n FROM users').get(),donations:db.prepare('SELECT COUNT(*) n FROM donations').get(),pendingNgos:db.prepare("SELECT COUNT(*) n FROM ngo_applications WHERE status='PENDING'").get(),available:db.prepare("SELECT COUNT(*) n FROM donations WHERE status='AVAILABLE'").get(),rescued:(db.prepare('SELECT COALESCE(SUM(received_quantity),0) n FROM receipts').get() as any).n,categories:db.prepare('SELECT c.name,COUNT(d.id) value FROM categories c LEFT JOIN donations d ON d.category_id=c.id GROUP BY c.id').all(),statuses:db.prepare('SELECT status,COUNT(*) value FROM donations GROUP BY status').all(),activity:db.prepare("SELECT date(created_at) day,COUNT(*) events,SUM(event_type='RECEIVED') rescues FROM timeline_events WHERE date(created_at)>=date('now','-13 day') GROUP BY date(created_at) ORDER BY day").all(),recent:db.prepare('SELECT e.*,u.name actor FROM timeline_events e LEFT JOIN users u ON u.id=e.actor_id ORDER BY e.id DESC LIMIT 8').all(),pendingApplications:db.prepare("SELECT a.id,u.name,u.email FROM ngo_applications a JOIN users u ON u.id=a.user_id WHERE a.status='PENDING' ORDER BY a.id LIMIT 6").all(),expiring:db.prepare("SELECT id,title,expires_at FROM donations WHERE status='AVAILABLE' AND expires_at>? ORDER BY expires_at LIMIT 6").all(new Date(Date.now()+24*3600000).toISOString()),unassigned:db.prepare("SELECT d.id,d.title FROM donations d WHERE d.status='CLAIMED' AND NOT EXISTS(SELECT 1 FROM assignments a WHERE a.donation_id=d.id AND a.status IN ('OFFERED','ACCEPTED')) LIMIT 6").all()}));
app.get('/api/admin/audit',roles('ADMIN'),(req,res)=>{const page=Math.max(1,Number(req.query.page)||1),limit=Math.min(50,Math.max(1,Number(req.query.limit)||20));res.json({items:db.prepare('SELECT a.*,u.name actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.id DESC LIMIT ? OFFSET ?').all(limit,(page-1)*limit),page,limit});});
app.get('/api/requirements',roles('NGO','ADMIN'),(req,res)=>{const u=res.locals.user as User;res.json(db.prepare(`SELECT r.*,c.name category FROM requirements r JOIN categories c ON c.id=r.category_id ${u.role==='ADMIN'?'':'WHERE r.ngo_id=?'} ORDER BY r.priority DESC,r.id`).all(...(u.role==='ADMIN'?[]:[u.id])));});
app.post('/api/requirements',roles('NGO'),(req,res)=>{const p=z.object({categoryId:z.number().int().positive(),quantity:z.number().positive(),priority:z.number().int().min(1).max(5),details:z.string().max(300).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Check category, quantity, and priority.'});const u=res.locals.user as User;if(!u.verified)return res.status(403).json({error:'Verified NGO status is required.'});const r=db.prepare('INSERT INTO requirements(ngo_id,category_id,quantity,priority,details) VALUES(?,?,?,?,?)').run(u.id,p.data.categoryId,p.data.quantity,p.data.priority,p.data.details??null);res.status(201).json({id:Number(r.lastInsertRowid)});});
app.delete('/api/requirements/:id',roles('NGO'),(req,res)=>{const r=db.prepare('DELETE FROM requirements WHERE id=? AND ngo_id=?').run(Number(req.params.id),(res.locals.user as User).id);if(!r.changes)return res.status(404).json({error:'Requirement not found.'});res.json({ok:true});});
app.get('/api/impact',(req,res)=>{const u=res.locals.user as User;const base=u.role==='DONOR'?'WHERE d.donor_id=?':u.role==='NGO'?'WHERE r.ngo_id=?':u.role==='VOLUNTEER'?'WHERE a.volunteer_id=?':'';const args=u.role==='ADMIN'?[]:[u.id];const row=db.prepare(`SELECT COALESCE(SUM(r.received_quantity),0) meals,COUNT(r.id) receipts FROM receipts r JOIN donations d ON d.id=r.donation_id LEFT JOIN claims c ON c.donation_id=d.id AND c.status='APPROVED' LEFT JOIN assignments a ON a.donation_id=d.id ${base}`).get(...args) as any;const kg=db.prepare("SELECT value FROM settings WHERE key='kg_per_meal'").get() as any,co2=db.prepare("SELECT value FROM settings WHERE key='co2_kg_per_kg'").get() as any;res.json({...estimatedImpact(row.meals,kg?.value??.4,co2?.value??2.5,row.receipts),receipts:row.receipts,label:'ESTIMATED IMPACT'});});
app.get('/api/forecast',roles('NGO'),(req,res)=>{const u=res.locals.user as User;const target=new Date();target.setDate(target.getDate()+1);const weekday=target.getDay();const records=db.prepare('SELECT category_id,demand,demand_date FROM demand_history WHERE ngo_id=?').all(u.id) as any[];const by=new Map<number,number[]>();for(const x of records)if(new Date(`${x.demand_date}T12:00:00`).getDay()===weekday){const a=by.get(x.category_id)??[];a.push(x.demand);by.set(x.category_id,a);}const categories=db.prepare('SELECT id,name FROM categories ORDER BY name').all() as any[];res.json(categories.map(c=>{const values=by.get(c.id)??[];return {category:c.name,forecast:values.length>=4?Number((values.reduce((a,b)=>a+b,0)/values.length).toFixed(1)):null,samples:values.length};}));});
app.get('/api/profile',(req,res)=>{const u=res.locals.user as User;res.json({...u,password_hash:undefined,requirements:u.role==='NGO'?db.prepare('SELECT * FROM requirements WHERE ngo_id=?').all(u.id):undefined});});
app.patch('/api/profile',auth,(req,res)=>{const p=z.object({name:z.string().trim().min(2).max(80).optional(),address:z.string().trim().max(250).optional(),lat:z.number().min(-90).max(90).optional(),lng:z.number().min(-180).max(180).optional(),capacity:z.number().positive().max(10000).optional(),available:z.boolean().optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Check your profile details.'});const u=res.locals.user as User;if(u.role==='VOLUNTEER')db.prepare('UPDATE users SET name=COALESCE(?,name),address=COALESCE(?,address),lat=COALESCE(?,lat),lng=COALESCE(?,lng),capacity=COALESCE(?,capacity),available=COALESCE(?,available) WHERE id=?').run(p.data.name??null,p.data.address??null,p.data.lat??null,p.data.lng??null,p.data.capacity??null,p.data.available===undefined?null:Number(p.data.available),u.id);else db.prepare('UPDATE users SET name=COALESCE(?,name),address=COALESCE(?,address),lat=COALESCE(?,lat),lng=COALESCE(?,lng) WHERE id=?').run(p.data.name??null,p.data.address??null,p.data.lat??null,p.data.lng??null,u.id);res.json(userQuery.get(u.id));});
app.get('/api/admin/ngos',roles('ADMIN'),(_req,res)=>res.json(db.prepare("SELECT a.*,u.name,u.email,u.address FROM ngo_applications a JOIN users u ON u.id=a.user_id WHERE a.status='PENDING' ORDER BY a.id").all()));
app.post('/api/admin/ngos/:id/decision',roles('ADMIN'),(req,res)=>{const p=z.object({decision:z.enum(['APPROVED','REJECTED']),reason:z.string().trim().max(500).optional()}).safeParse(req.body);if(!p.success||p.data.decision==='REJECTED'&&!p.data.reason)return res.status(400).json({error:'A rejection reason is required.'});const id=Number(req.params.id),application=db.prepare('SELECT * FROM ngo_applications WHERE id=? AND status=\'PENDING\'').get(id) as any;if(!application)return res.status(404).json({error:'Pending application not found.'});db.transaction(()=>{db.prepare('UPDATE ngo_applications SET status=?,reason=? WHERE id=?').run(p.data.decision,p.data.reason??null,id);db.prepare('UPDATE users SET verified=? WHERE id=?').run(Number(p.data.decision==='APPROVED'),application.user_id);notify(application.user_id,p.data.decision==='APPROVED'?'NGO application approved':'NGO application update',p.data.decision==='APPROVED'?'Your organisation can now request food.':`Your application needs attention: ${p.data.reason}`, '/profile',`ngo-${id}-${p.data.decision}`);audit((res.locals.user as User).id,`NGO_${p.data.decision}`,'ngo_application',id,p.data.reason);})();res.json({ok:true});});
app.get('/api/admin/settings',roles('ADMIN'),(_req,res)=>res.json(db.prepare('SELECT key,value FROM settings').all()));
app.patch('/api/admin/settings',roles('ADMIN'),(req,res)=>{const p=z.object({kg_per_meal:z.number().positive().max(5).optional(),co2_kg_per_kg:z.number().positive().max(20).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Impact factors must be positive and within limits.'});for(const [key,value] of Object.entries(p.data))if(value!==undefined)db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(key,value);audit((res.locals.user as User).id,'SETTINGS_UPDATED','settings',undefined,JSON.stringify(p.data));res.json({ok:true});});
function csv(rows:any[],columns:string[]){const quote=(v:unknown)=>{let text=String(v??'');if(/^\s*[=+\-@]/.test(text))text=`'${text}`;return `"${text.replaceAll('"','""')}"`;};return [columns.map(quote).join(','),...rows.map(row=>columns.map(key=>quote(row[key])).join(','))].join('\r\n');}
app.get('/api/admin/export/donations.csv',roles('ADMIN'),(req,res)=>{const p=z.object({status:z.enum(['AVAILABLE','CLAIMED','VOLUNTEER_ASSIGNED','PICKUP_STARTED','PICKED_UP','IN_TRANSIT','DELIVERED','RECEIVED','CANCELLED','EXPIRED']).optional(),from:z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),to:z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional()}).safeParse(req.query);if(!p.success)return res.status(400).json({error:'Invalid CSV filters.'});const where:string[]=[],args:unknown[]=[];if(p.data.status){where.push('d.status=?');args.push(p.data.status);}if(p.data.from){where.push('date(d.created_at)>=date(?)');args.push(p.data.from);}if(p.data.to){where.push('date(d.created_at)<=date(?)');args.push(p.data.to);}const rows=db.prepare(`SELECT d.id,d.title,c.name category,d.quantity,d.available_quantity,d.claimed_quantity,d.reserved_quantity,d.delivered_quantity,d.unit,d.status,d.expires_at,u.name donor FROM donations d JOIN categories c ON c.id=d.category_id JOIN users u ON u.id=d.donor_id ${where.length?'WHERE '+where.join(' AND '):''} ORDER BY d.id`).all(...args);audit((res.locals.user as User).id,'CSV_EXPORT','donations');res.type('text/csv').attachment('smartfood-donations.csv').send(csv(rows,['id','title','category','quantity','available_quantity','claimed_quantity','reserved_quantity','delivered_quantity','unit','status','expires_at','donor']));});
app.get('/api/admin/export/deliveries.csv',roles('ADMIN'),(req,res)=>{const rows=db.prepare('SELECT d.id,d.title,x.expected_quantity,x.delivered_quantity,x.received_quantity,x.recipient_name,x.accepted,x.created_at FROM deliveries x JOIN donations d ON d.id=x.donation_id ORDER BY x.id').all();audit((res.locals.user as User).id,'CSV_EXPORT','deliveries');res.type('text/csv').attachment('smartfood-deliveries.csv').send(csv(rows,['id','title','expected_quantity','delivered_quantity','received_quantity','recipient_name','accepted','created_at']));});
app.get('/api/recommendations',roles('NGO'),(req,res)=>{const u=res.locals.user as User;if(!u.verified)return res.json([]);const reqs=db.prepare('SELECT category_id,quantity FROM requirements WHERE ngo_id=? AND active=1').all(u.id) as any[];const dList=db.prepare("SELECT d.*,c.name category FROM donations d JOIN categories c ON c.id=d.category_id WHERE d.status='AVAILABLE' AND d.expires_at>? AND d.available_quantity>0 ORDER BY d.expires_at LIMIT 100").all(new Date().toISOString()) as any[];const matches=dList.map(d=>{const distance=u.lat==null?null:haversineKm({lat:u.lat,lng:u.lng!},{lat:d.lat,lng:d.lng});const hasCategory=reqs.some(r=>r.category_id===d.category_id),availableCapacity=Math.max(...reqs.filter(r=>r.category_id===d.category_id).map(r=>r.quantity),0);const ratings=(db.prepare('SELECT stars FROM ratings WHERE rated_id=?').all(u.id) as {stars:number}[]).map(x=>x.stars),completed=(db.prepare('SELECT COUNT(*) n FROM receipts WHERE ngo_id=?').get(u.id) as any).n,approved=(db.prepare("SELECT COUNT(*) n FROM claims WHERE ngo_id=? AND status='APPROVED'").get(u.id) as any).n,reliability=reliabilityScore(ratings,completed,0),performance=approved?Math.round(completed/approved*100):75;const score=ngoMatchScore({category:hasCategory?100:45,requirement:hasCategory?100:30,distance:distance==null?40:Math.max(0,100-distance/30*100),urgency:urgency(d.expires_at).score,reliability,capacity:availableCapacity>=d.available_quantity?100:Math.min(100,availableCapacity/Math.max(d.available_quantity,1)*100),performance});return {...d,distanceKm:distance==null?null:Number(distance.toFixed(1)),matchScore:score,matchExplanation:`${hasCategory?'Matches your active category needs':'Nearby food option'}${availableCapacity>=d.available_quantity?', has capacity':''}${distance==null?'':`, ${distance.toFixed(1)} km away`}.`};}).filter(d=>d.distanceKm==null||d.distanceKm<=30).sort((a,b)=>b.matchScore-a.matchScore);res.json(matches);});
if(process.env.NODE_ENV==='production'){const clientDir=path.resolve('dist');app.use(express.static(clientDir));app.get('*',(_req,res,next)=>{if(_req.path.startsWith('/api/'))return next();res.sendFile(path.join(clientDir,'index.html'));});}
app.use((err:unknown,_req:express.Request,res:express.Response,_next:express.NextFunction)=>{const info=err as {status?:number;message?:string};const status=info.status??500;if(status>=500)console.error('Request failed:',info.message??'unknown error');res.status(status).json({error:status<500?info.message??'Invalid request.':'Something went wrong. Please try again.'});});
const port=Number(process.env.PORT??3001);
if(process.env.NODE_ENV!=='test'){app.listen(port,()=>console.log(`SmartFood API listening on http://localhost:${port}`));runMaintenance();setInterval(runMaintenance,30_000).unref();}
export { app };
